<template><div class="app-container quality-inventory"><el-alert title="冻结与解冻按原批次和原来源处理；次品转正须先核对仓库质检结果。审核成功才变更库存，原入库实收记录保留。" type="info" :closable="false"/><el-form class="filters" inline size="small" @submit.native.prevent="search"><el-form-item label="质量单号"><el-input v-model.trim="query.quality_sn" clearable/></el-form-item><el-form-item label="SKU"><el-input v-model.trim="query.sku_sn" clearable/></el-form-item><el-form-item label="虚仓编码"><el-input v-model.trim="query.store_code" clearable/></el-form-item><el-form-item label="审核结果"><el-select v-model="query.state" clearable><el-option v-for="(label,key) in states" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><div class="toolbar"><el-button v-hasPermi="['inventory:quality:create']" type="primary" size="small" @click="newForm()">新增质量处理</el-button><el-button size="small" @click="load">刷新列表</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <el-table :data="rows" v-loading="loading" size="small"><el-table-column label="质量单 / 处理方式" min-width="285"><template slot-scope="{row}"><el-button type="text" @click="show(row.id)">{{row.quality_sn}}</el-button><div class="muted">{{actions[row.action]}}</div></template></el-table-column><el-table-column label="SKU / 虚仓 / 批次" min-width="260"><template slot-scope="{row}"><strong>{{row.sku_sn}}</strong><div class="muted">{{row.store_code}}</div><div class="muted">{{row.batch_code}}</div></template></el-table-column><el-table-column label="数量 / 质量" width="130"><template slot-scope="{row}">{{row.quantity}}<div>{{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column label="当前结果" width="150"><template slot-scope="{row}"><el-tag size="mini" :type="row.state==='COMPLETED'?'success':row.state==='REJECTED'?'info':'warning'">{{states[row.state]}}</el-tag></template></el-table-column><el-table-column label="申请 / 审核人" min-width="160"><template slot-scope="{row}">{{row.created_by}}<div class="muted">{{row.reviewed_by||'待审核'}}</div></template></el-table-column><el-table-column prop="reason" label="处理原因" min-width="230"/><el-table-column label="最近处理" min-width="165"><template slot-scope="{row}">{{time(row.update_time)}}</template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/>
 <el-dialog title="申请库存质量处理" :visible.sync="editing" width="950px" append-to-body :close-on-click-modal="false"><el-form label-position="top" size="small"><div class="grid"><el-form-item label="处理方式"><el-select v-model="form.action" :disabled="!!form.source_sn" @change="actionChanged"><el-option label="冻结库存" value="FREEZE"/><el-option label="按原冻结单解冻" value="UNFREEZE"/><el-option label="次品转正" value="CP_TO_ZP"/></el-select></el-form-item><el-form-item label="库存质量"><el-select v-model="form.inventory_type" :disabled="!!form.source_sn||form.action==='CP_TO_ZP'"><el-option label="正品" value="ZP"/><el-option label="次品" value="CP"/></el-select></el-form-item></div><div class="grid"><el-form-item label="完整SKU"><el-input v-model.trim="batchQuery.sku"/></el-form-item><el-form-item label="虚仓编码（可选）"><el-input v-model.trim="batchQuery.store"/></el-form-item></div><el-button :loading="batchLoading" @click="loadBatches">查询实际库存批次</el-button><el-alert v-if="batchError" :title="batchError" type="error" :closable="false"/><el-form-item label="实际库存批次"><el-select v-model="form.batch_id" filterable :disabled="!!form.source_sn" placeholder="先查询再选择原批次"><el-option v-for="b in batches" :key="b.id" :value="Number(b.id)" :label="b.store_code+' / '+b.batch_code+' · 正品可用 '+b.zp_available_number+'，次品可用 '+b.cp_available_number"/></el-select></el-form-item><el-alert v-if="selectedBatch" :title="'当前原批次：正品 '+selectedBatch.zp_actual_number+'，次品 '+selectedBatch.cp_actual_number+'；正品可用 '+selectedBatch.zp_available_number+'，次品可用 '+selectedBatch.cp_available_number+'。审核时再次核对库存。'" type="info" :closable="false"/><el-form-item v-if="form.action==='UNFREEZE'" label="原冻结单号"><el-input v-model.trim="form.source_sn" placeholder="从已审核冻结单点击“按本来源解冻”可自动带入"/></el-form-item><el-form-item label="本次处理数量"><el-input-number v-model="form.quantity" :min="1" :max="100000000" :precision="0"/></el-form-item><el-form-item label="处理原因"><el-input v-model.trim="form.reason" type="textarea" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="质检凭证 / 冻结或解冻依据"><el-input v-model.trim="form.evidence" type="textarea" maxlength="1000" show-word-limit/></el-form-item><el-form-item v-if="form.action==='CP_TO_ZP'"><el-checkbox v-model="form.warehouse_confirmed">已核对仓库实际质检结果，同意将上述数量的次品转为正品</el-checkbox><p class="muted">本操作登记已确认的仓库质量结果。请先取得仓库质检凭证；当前不会调用奇门库存质量变更接口。</p></el-form-item></el-form><el-alert v-if="submitError" :title="submitError" type="error" :closable="false"/><span slot="footer"><el-button :disabled="busy" @click="editing=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">提交质量处理申请</el-button></span></el-dialog>
 <el-drawer :visible.sync="visible" title="质量库存处理详情" size="78%" append-to-body><section v-if="detail" class="quality-detail" v-loading="detailLoading"><header><h2>{{detail.quality_sn}}</h2><el-button size="small" @click="show(detail.id)">刷新详情</el-button></header><el-alert :title="states[detail.state]+' · '+actions[detail.action]" :type="detail.state==='COMPLETED'?'success':'info'" :closable="false"/><el-descriptions :column="2" border size="small"><el-descriptions-item label="库存SKU">{{detail.sku_sn}}</el-descriptions-item><el-descriptions-item label="原虚仓 / 批次">{{detail.store_code}} / {{detail.batch_code}}</el-descriptions-item><el-descriptions-item label="处理数量 / 原质量">{{detail.quantity}} / {{detail.inventory_type==='ZP'?'正品':'次品'}}</el-descriptions-item><el-descriptions-item label="原冻结来源">{{detail.source_sn||'本单为独立申请'}}</el-descriptions-item><el-descriptions-item label="当前批次正品 / 次品">{{detail.zp_actual_number}} / {{detail.cp_actual_number}}</el-descriptions-item><el-descriptions-item label="当前批次正品可用 / 次品可用">{{detail.zp_available_number}} / {{detail.cp_available_number}}</el-descriptions-item><el-descriptions-item label="申请人 / 时间">{{detail.created_by}} / {{time(detail.create_time)}}</el-descriptions-item><el-descriptions-item label="审核人 / 时间">{{detail.reviewed_by||'尚未审核'}} / {{time(detail.update_time)}}</el-descriptions-item><el-descriptions-item label="原因">{{detail.reason}}</el-descriptions-item><el-descriptions-item label="质检或处理凭证">{{detail.evidence}}</el-descriptions-item><el-descriptions-item label="审核依据">{{detail.review_reason||'尚未审核'}}</el-descriptions-item><el-descriptions-item label="仓库质检确认">{{detail.warehouse_confirmed?'已登记确认依据':'本操作无需质量转正确认'}}</el-descriptions-item></el-descriptions><el-alert v-if="detail.action==='CP_TO_ZP'" title="次品转正保持实物总库存和原入库实收不变，质量变化分别生成次品减少、正品增加两条库存流水。" type="info" :closable="false"/>
 <div v-if="detail.state==='DRAFT'" v-hasPermi="['inventory:quality:review']"><el-form label-position="top"><el-form-item label="审核依据"><el-input v-model.trim="reviewReason" type="textarea" maxlength="1000"/></el-form-item></el-form><el-button type="primary" :loading="busy" @click="review('APPROVE')">审核并执行库存处理</el-button><el-button :disabled="busy" @click="review('REJECT')">驳回申请</el-button></div>
 <template v-if="detail.action==='FREEZE'&&detail.state==='COMPLETED'&&detail.stock"><h3>原冻结来源余额</h3><el-table :data="detail.stock.lines" size="small"><el-table-column prop="sku_sn" label="实际SKU" min-width="230"/><el-table-column prop="batch_code" label="原批次"/><el-table-column prop="quantity" label="原冻结"/><el-table-column prop="released_quantity" label="已解冻"/><el-table-column label="剩余冻结"><template slot-scope="{row}">{{Number(row.quantity)-Number(row.released_quantity)}}</template></el-table-column></el-table><el-button v-hasPermi="['inventory:quality:create']" :disabled="!remaining" size="small" @click="newForm(detail)">按本来源解冻</el-button></template><p class="muted">当前批次数量会随后续业务变化；本单处理事实、依据及审核结果保持追溯。</p></section></el-drawer>
</div></template>
<script>
import {qualityList,qualityDetail,qualityBatches,createQuality,reviewQuality} from '@/api/inventory/quality'
const defaults=()=>({quality_sn:'',sku_sn:'',store_code:'',state:'',pageNum:1,pageSize:20})
const fresh=()=>({request_key:'QA'+Date.now()+Math.random().toString(36).slice(2),action:'FREEZE',inventory_type:'ZP',batch_id:null,quantity:1,source_sn:'',reason:'',evidence:'',warehouse_confirmed:false})
export default{data:()=>({query:defaults(),rows:[],total:0,loading:false,error:'',sequence:0,detailSequence:0,batchSequence:0,editing:false,visible:false,detail:null,detailLoading:false,reviewReason:'',form:fresh(),batches:[],batchQuery:{sku:'',store:''},batchLoading:false,batchError:'',busy:false,submitError:'',states:{DRAFT:'待审核',COMPLETED:'已审核执行',REJECTED:'已驳回'},actions:{FREEZE:'冻结库存',UNFREEZE:'按原来源解冻',CP_TO_ZP:'次品转正'}}),computed:{selectedBatch(){return this.batches.find(b=>Number(b.id)===Number(this.form.batch_id))},remaining(){return this.detail&&this.detail.stock?(this.detail.stock.lines||[]).reduce((n,l)=>n+Number(l.quantity)-Number(l.released_quantity),0):0}},created(){if(this.$route.query.sku)this.query.sku_sn=this.$route.query.sku;this.load();if(this.$route.query.id)this.show(Number(this.$route.query.id))},beforeDestroy(){this.sequence++;this.detailSequence++;this.batchSequence++},methods:{time(v){return v?String(v).replace('T',' ').slice(0,19):'—'},search(){this.query.pageNum=1;this.load()},reset(){this.query=defaults();this.load()},async load(){const seq=++this.sequence;this.loading=true;this.error='';try{const r=(await qualityList(this.query)).data;if(seq===this.sequence){this.rows=r.rows;this.total=Number(r.total)}}catch(_){if(seq===this.sequence)this.error='质量处理记录查询失败，请刷新重试'}finally{if(seq===this.sequence)this.loading=false}},async show(id){const seq=++this.detailSequence;this.visible=true;this.detailLoading=true;this.reviewReason='';try{const r=(await qualityDetail(id)).data;if(seq===this.detailSequence)this.detail=r}finally{if(seq===this.detailSequence)this.detailLoading=false}},newForm(source){this.form=fresh();this.submitError='';this.batchError='';this.batches=[];this.batchQuery={sku:source?source.sku_sn:this.query.sku_sn,store:source?source.store_code:this.query.store_code};if(source){this.form.action='UNFREEZE';this.form.inventory_type=source.inventory_type;this.form.source_sn=source.quality_sn;this.form.batch_id=Number(source.batch_id);this.form.quantity=this.remaining}this.editing=true;if(this.batchQuery.sku)this.loadBatches()},actionChanged(){if(this.form.action==='CP_TO_ZP')this.form.inventory_type='CP';this.form.warehouse_confirmed=false},async loadBatches(){if(!this.batchQuery.sku)return this.$message.warning('请填写完整SKU');const seq=++this.batchSequence;this.batchLoading=true;this.batchError='';try{const rows=(await qualityBatches(this.batchQuery)).data;if(seq===this.batchSequence)this.batches=rows}catch(e){if(seq===this.batchSequence)this.batchError=e.message||'库存批次查询失败'}finally{if(seq===this.batchSequence)this.batchLoading=false}},async save(){if(this.busy)return;if(!this.form.batch_id||!this.form.reason||!this.form.evidence)return this.$message.warning('请选择原批次并填写原因与凭证');if(this.form.action==='CP_TO_ZP'&&!this.form.warehouse_confirmed)return this.$message.warning('请先核对仓库质检结果并勾选确认');this.busy=true;this.submitError='';try{const id=(await createQuality(this.form)).data;this.editing=false;await this.load();await this.show(id)}catch(e){this.submitError=e.message||'质量处理申请保存失败'}finally{this.busy=false}},async review(decision){if(this.busy)return;if(this.reviewReason.length<2)return this.$message.warning('请填写至少2字审核依据');this.busy=true;try{await reviewQuality(this.detail.id,{control_version:this.detail.control_version,decision,reason:this.reviewReason});await this.show(this.detail.id);this.load();this.$message.success(decision==='APPROVE'?'质量处理已执行，可核对原批次和库存流水':'已驳回，库存保持原数量')}finally{this.busy=false}}}}
</script>
<style scoped>.filters{margin:20px 0}.toolbar,header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:18px 0}.toolbar{justify-content:flex-start}.toolbar .el-button{margin:0}.muted{font-size:12px;line-height:1.8;color:#7a899d;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.el-select{width:100%}.el-alert,.el-descriptions{margin:16px 0}.quality-detail{padding:0 24px 36px}.quality-detail h2{font-size:20px;overflow-wrap:anywhere}.quality-inventory ::v-deep .cell{overflow-wrap:anywhere}.quality-inventory ::v-deep .el-button--text{white-space:normal;text-align:left}</style>
